// SPDX-License-Identifier: Apache-2.0
// miopen seed for FlashInfer-Bench/025_rmsnorm_h4096.
//
// Exists to prove the hipcc + -lMIOpen path end to end. MIOpen's T5 LayerNorm
// *is* RMSNorm -- normalize by the root mean square, scale by a learned
// weight, no mean subtraction and no bias -- so it maps onto this problem
// without reinterpretation.
//
// Two things are not optional and are easy to miss:
//   * the LayerNorm entry points sit behind MIOPEN_BETA_API, so the define
//     must precede the include or the symbol simply is not declared;
//   * MIOpen keeps its own stream. Without miopenSetStream() the work is
//     issued on MIOpen's default stream, outside the harness's timing
//     bracket -- which does not fail, it just measures the wrong thing.
#define MIOPEN_BETA_API 1

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <c10/hip/HIPStream.h>
#include <miopen/miopen.h>

#include <stdexcept>
#include <string>
#include <vector>

namespace {

#define CHECK_MIOPEN(expr)                                                   \
  do {                                                                       \
    miopenStatus_t _s = (expr);                                              \
    if (_s != miopenStatusSuccess) {                                         \
      throw std::runtime_error(std::string("miopen failed: " #expr " -> ")   \
                               + std::to_string(static_cast<int>(_s)));      \
    }                                                                        \
  } while (0)

miopenHandle_t get_handle() {
  static miopenHandle_t handle = [] {
    miopenHandle_t h = nullptr;
    CHECK_MIOPEN(miopenCreate(&h));
    return h;
  }();
  return handle;
}

struct TensorDesc {
  miopenTensorDescriptor_t d = nullptr;
  TensorDesc(miopenDataType_t dt, std::vector<int> dims,
             std::vector<int> strides) {
    CHECK_MIOPEN(miopenCreateTensorDescriptor(&d));
    CHECK_MIOPEN(miopenSetTensorDescriptor(
        d, dt, static_cast<int>(dims.size()), dims.data(), strides.data()));
  }
  ~TensorDesc() { miopenDestroyTensorDescriptor(d); }
  TensorDesc(const TensorDesc&) = delete;
  TensorDesc& operator=(const TensorDesc&) = delete;
};

constexpr int kHidden = 4096;

}  // namespace

torch::Tensor run(const torch::Tensor& hidden_states,
                  const torch::Tensor& weight) {
  TORCH_CHECK(hidden_states.dim() == 2, "hidden_states must be 2D");
  TORCH_CHECK(hidden_states.size(1) == kHidden, "hidden_size must be 4096");
  TORCH_CHECK(hidden_states.scalar_type() == torch::kBFloat16, "bf16 only");
  TORCH_CHECK(weight.scalar_type() == torch::kBFloat16, "bf16 only");

  auto x = hidden_states.contiguous();
  auto w = weight.contiguous();
  auto y = torch::empty_like(x);

  const int rows = static_cast<int>(x.size(0));
  // rstd is an output MIOpen requires even though this problem does not want
  // it; it is fp32 because that is the accumulation type of the reduction.
  auto rstd = torch::empty({rows}, x.options().dtype(torch::kFloat32));

  TensorDesc xd(miopenBFloat16, {rows, kHidden}, {kHidden, 1});
  TensorDesc yd(miopenBFloat16, {rows, kHidden}, {kHidden, 1});
  TensorDesc wd(miopenBFloat16, {kHidden}, {1});
  TensorDesc rd(miopenFloat, {rows}, {1});

  miopenHandle_t handle = get_handle();
  CHECK_MIOPEN(miopenSetStream(handle, c10::hip::getCurrentHIPStream()));

  CHECK_MIOPEN(miopenT5LayerNormForward(
      handle, MIOPEN_WEIGHT_BIAS_T5, xd.d, x.data_ptr(), wd.d, w.data_ptr(),
      1e-5f, yd.d, y.data_ptr(), rd.d, rstd.data_ptr()));

  return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("run", &run, "RMSNorm h4096 bf16 via MIOpen T5LayerNorm (miopen seed)");
}
